const uid=()=>crypto.randomUUID();
function iso(d=new Date()){return d.getFullYear()+'-'+('0'+(d.getMonth()+1)).slice(-2)+'-'+('0'+d.getDate()).slice(-2)}
const now=()=>new Date().toISOString();
const clock=s=>{const n=Math.max(0,Math.ceil(s));return ('0'+Math.floor(n/60)).slice(-2)+':'+('0'+n%60).slice(-2)};
const dateLabel=s=>new Date(s+'T12:00:00').toLocaleDateString('en-IL',{weekday:'long',month:'short',day:'numeric'});
function seed(){const today=iso();return [
 {id:uid(),kind:'routine',payload:{group:'Morning',title:'Get dressed',emoji:'👕',done_on:''},created_at:now()},
 {id:uid(),kind:'routine',payload:{group:'Morning',title:'Breakfast',emoji:'🥣',done_on:''},created_at:now()},
 {id:uid(),kind:'routine',payload:{group:'After school',title:'Snack and quiet time',emoji:'🍎',done_on:''},created_at:now()},
 {id:uid(),kind:'routine',payload:{group:'After school',title:'Movement or outdoor time',emoji:'🌿',done_on:''},created_at:now()},
 {id:uid(),kind:'routine',payload:{group:'Bedtime',title:'Brush teeth',emoji:'🪥',done_on:''},created_at:now()},
 {id:uid(),kind:'routine',payload:{group:'Bedtime',title:'Bedtime reading',emoji:'📖',done_on:''},created_at:now()},
 {id:uid(),kind:'schedule',payload:{title:'Example: FIFA session',date:today,time:'17:00',category:'Screen'},created_at:now()}
]}
function loadDemo(){try{let x=JSON.parse(localStorage.getItem(KEY)||'null');if(Array.isArray(x))return x;}catch{}return seed()}
let state={tab:'today',mode:localStorage.getItem('gfh_mode')==='cloud'?'cloud':'demo',items:loadDemo(),client:null,user:null,family:null,active:0,month:new Date(new Date().getFullYear(),new Date().getMonth(),1),selected:iso(),warnings:new Set(),authStep:'signin',busy:false};
function list(kind){return state.items.filter(x=>x.kind===kind)}
