function message(s){const n=$('notice');n.textContent=s;clearTimeout(window.__gfhNot);window.__gfhNot=setTimeout(updateStatus,5500)}
function updateStatus(){const inFamily=state.mode==='cloud'&&state.family&&state.user;$('status').textContent=inFamily?'PRIVATE • SYNCED':state.mode==='cloud'?'PARENT LOGIN':'DEMO • THIS PHONE';$('notice').textContent=inFamily?'Private family space. Edits are shared with authorized parents only.':state.mode==='cloud'?'Parent sign-in required before real family records are available.':'Preview mode. Use fictional examples only. Changes stay on this phone. Nothing is shared.'}
function nav(){let all=TABS.concat(EXTRAS);$('side').innerHTML='<div class="eyebrow" style="margin:8px 9px">FAMILY SPACE</div>'+all.filter(x=>x[0]!=='more').map(x=>'<button data-tab="'+x[0]+'" class="'+(state.tab===x[0]?'on':'')+'"><span style="font-size:20px;margin-right:8px">'+x[1]+'</span>'+x[2]+'</button>').join('');$('bottom').innerHTML=TABS.map(x=>'<button data-tab="'+x[0]+'" class="'+(state.tab===x[0]?'on':'')+'"><span>'+x[1]+'</span>'+x[2]+'</button>').join('')}
function heading(t,sub){return '<div class="eyebrow">GAVRIEL FAMILY HUB</div><h1>'+t+'</h1><p class="lead">'+sub+'</p>'}
function safety(){return '<div class="card safety"><div class="row"><h2 style="margin:0">What should we do right now?</h2><span class="tag">SAFETY FIRST</span></div><ol><li>Separate children and check for injury. Call emergency services if anyone is in immediate danger.</li><li>Use one calm phrase: “I won’t let you hit.” Avoid arguing or wrestling over devices.</li><li>Lower demands, offer physical space, and keep siblings supervised.</li><li>When everyone is calm, reconnect and practice a safer choice.</li></ol><p class="tiny muted">This is a starter safety plan, not individualized clinical advice. Review it with a qualified professional.</p></div>'}
function scheduleFor(day){
 const weekday=new Date(day+'T12:00:00').getDay();
 return list('schedule').filter(item=>{
   const p=item.payload||{};
   if(p.repeat==='weekly' && Array.isArray(p.weekdays))
     return (!p.date || day>=p.date) && p.weekdays.includes(weekday);
   if(p.repeat==='daily')return !p.date || day>=p.date;
   return p.date===day;
 }).sort((a,b)=>String(a.payload.time||'').localeCompare(String(b.payload.time||'')));
}
function eventRows(day){
 const rows=scheduleFor(day);
 if(!rows.length)return '<p class="muted tiny">No events yet.</p>';
 return rows.map(item=>{
  const p=item.payload;
  const recurring=p.repeat==='weekly'&&Array.isArray(p.weekdays);
  const repeatNote=recurring ? ((p.weekdays.length===6&&[0,1,2,3,4,5].every(x=>p.weekdays.includes(x)))?' · Every Sun–Fri':' · Repeats weekly') : p.repeat==='daily'?' · Every day':'';
  return '<div class="item row"><div><strong>'+esc(p.time||'')+(p.end_time?'–'+esc(p.end_time):'')+' · '+esc(p.title)+'</strong><small>'+esc(p.category||'Routine')+repeatNote+'</small></div><button class="btn soft" data-delete="'+item.id+'">×</button></div>';
 }).join('');
}
function renderToday(){let routines=list('routine'),done=routines.filter(x=>x.payload.done_on===iso()).length,wins=list('achievement').filter(x=>x.payload.date===iso()).length;return heading('Today, together',dateLabel(iso())+' · Shared structure and calmer transitions')+'<div class="hero"><div class="eyebrow" style="color:#b8ded2">TODAY’S FOCUS</div><h2>Predictability over arguments.</h2><p>Show the next step, agree on FIFA time first, celebrate safe choices, and use one consistent response.</p><button class="btn light" data-tab="routines">Open visual routines →</button></div><div class="grid"><div class="card"><div class="row"><h2>Today’s progress</h2><button class="btn soft" data-tab="progress">See wins</button></div><p><strong style="font-size:28px">'+done+' / '+routines.length+'</strong> <span class="muted">routine steps complete</span></p><div class="track"><div style="width:'+(routines.length?done/routines.length*100:0)+'%"></div></div><p class="muted tiny">'+wins+' positive moments recorded today.</p></div><div class="card"><div class="row"><h2>FIFA timer</h2><button class="btn soft" data-tab="fifa">Open</button></div>'+timerShort()+'<p class="muted tiny">Warnings at 10, 5, and 1 minute while the app is open.</p></div></div><div class="grid"><div class="card"><div class="row"><h2>Today’s calendar</h2><button class="btn soft" data-tab="calendar">View</button></div>'+eventRows(iso())+'</div><div class="card"><div class="row"><h2>Latest parent note</h2><button class="btn soft" data-tab="handover">Handover</button></div>'+handoverPreview()+'</div></div><div class="row"><button class="btn" data-action="safety">What should we do right now?</button><button class="btn soft" data-tab="behavior">Quick observation</button></div>'}
function renderRoutines(){const a=list('routine'),groups=['Morning','After school','Bedtime'],today=iso();let body=groups.map(group=>{let rows=a.filter(x=>x.payload.group===group);let done=rows.filter(x=>x.payload.done_on===today).length;return '<div class="card"><div class="row"><h2>'+group+'</h2><span class="tag">'+done+' / '+rows.length+' done</span></div>'+rows.map((x,i)=>{let p=x.payload,d=p.done_on===today;return '<div class="routine '+(d?'done':'')+'"><span class="emoji">'+esc(p.emoji||'⭐')+'</span><div class="words"><strong>'+esc(p.title)+'</strong><div class="tiny muted">'+(d?'Finished today':'Tap when complete')+'</div></div><button class="btn '+(d?'soft':'')+'" data-check="'+x.id+'">'+(d?'✓ Done':'Mark ✓')+'</button><button class="btn soft" data-delete="'+x.id+'" aria-label="Delete routine">×</button></div>'}).join('')+(rows.length===0?'<p class="muted tiny">Add a step below.</p>':'')+'</div>'}).join('');const next=a.find(x=>x.payload.done_on!==today);return heading('Visual daily routines','Picture prompts and a simple First → Then sequence.')+(next?'<div class="hero"><div class="eyebrow" style="color:#c5e6d8">FIRST → THEN</div><h2>'+esc(next.payload.emoji||'⭐')+' '+esc(next.payload.title)+'</h2><p>Finish this step, then move to the next item in the routine.</p><button class="btn light" data-check="'+next.id+'">Completed ✓</button></div>':'<div class="hero"><h2>All steps complete!</h2><p>Add another routine or celebrate the win.</p></div>')+body+'<div class="card"><h2>Add a visual step</h2><form class="form" data-form="routine"><label>Routine<select name="group"><option>Morning</option><option>After school</option><option>Bedtime</option></select></label><label>Picture emoji<input name="emoji" maxlength="4" value="⭐"></label><label>Step title<input name="title" maxlength="90" required placeholder="e.g. Put shoes on"></label><button class="btn">Add routine step</button></form></div>'}
function renderCalendar(){const y=state.month.getFullYear(),m=state.month.getMonth();let days=new Date(y,m+1,0).getDate(),offset=new Date(y,m,1).getDay(),cells=['S','M','T','W','T','F','S'].map(x=>'<strong class="muted tiny" style="text-align:center">'+x+'</strong>').join('');for(let i=0;i<offset;i++)cells+='<i></i>';for(let n=1;n<=days;n++){let d=y+'-'+('0'+(m+1)).slice(-2)+'-'+('0'+n).slice(-2);cells+='<button class="'+(state.selected===d?'on':'')+'" data-day="'+d+'">'+n+(scheduleFor(d).length?'<span style="display:block;width:5px;height:5px;border-radius:50%;background:#2d9878;margin:1px auto"></span>':'')+'</button>'}return heading('Family calendar','See upcoming activities, routines, school, and scheduled screen time.')+'<div class="grid"><div class="card"><div class="row"><button class="btn soft" data-month="-1">‹</button><h2>'+state.month.toLocaleDateString('en-IL',{month:'long',year:'numeric'})+'</h2><button class="btn soft" data-month="1">›</button></div><div class="cal">'+cells+'</div></div><div class="card"><h2>'+dateLabel(state.selected)+'</h2>'+eventRows(state.selected)+'<form class="form" data-form="schedule"><label>Event<input required name="title" maxlength="100" placeholder="Add an activity"></label><div class="twocol"><label>Date<input type="date" name="date" value="'+state.selected+'" required></label><label>Time<input type="time" name="time" value="17:00"></label></div><label>Category<select name="category"><option>Routine</option><option>School</option><option>Appointment</option><option>Screen</option><option>Meal</option><option>Activity</option></select></label><label>Repeat<select name="repeat"><option value="none">One-time event</option><option value="sunfri">Every Sunday–Friday</option><option value="weekly">Weekly on this weekday</option><option value="daily">Every day</option></select></label><button class="btn">Add event</button></form></div></div>'}
function activeSession(){return list('screen').filter(x=>x.payload.status==='running').sort((a,b)=>String(b.created_at).localeCompare(String(a.created_at)))[0]}
function timerShort(){const a=activeSession();if(!a)return '<div class="muted tiny">No active session. Agree on a finish time before starting.</div>';const secs=(new Date(a.payload.ends_at)-Date.now())/1000;return '<strong style="font-size:27px;color:#276d5b">'+clock(secs)+'</strong> <span class="tiny">'+esc(a.payload.game||'FIFA')+'</span>'}
function renderFifa(){const a=activeSession();let part='';if(a){const p=a.payload,left=(new Date(p.ends_at)-Date.now())/1000,total=p.minutes*60;part='<div class="card" style="text-align:center"><div class="eyebrow" id="timerStatus">SESSION IN PROGRESS</div><div class="clock" id="bigClock">'+clock(left)+'</div><div class="track"><div id="timerFill" style="width:'+Math.max(0,Math.min(100,left/total*100))+'%"></div></div><p class="muted tiny" id="timerHint">'+(left>0?'End of current match before the clock reaches zero.':'Time is up. Calmly offer the next activity.')+'</p><div class="note"><strong>Agreed:</strong> '+esc(p.matches||'No set match count')+' matches · <strong>Next:</strong> '+esc(p.next||'Family activity')+'</div><div class="spacer"></div><button class="btn full" data-action="finish">Controller handed back</button></div>'}else{part='<div class="card"><h2>Plan a FIFA session</h2><form class="form" data-form="screen"><label>Game<select name="game"><option>FIFA</option><option>Other game</option><option>YouTube / video</option><option>Other device</option></select></label><label>Time limit<select name="minutes"><option value="15">15 minutes</option><option value="20">20 minutes</option><option value="30" selected>30 minutes</option><option value="45">45 minutes</option><option value="60">60 minutes</option></select></label><label>Agreed matches<input type="number" name="matches" min="1" max="20" value="2"></label><label>What comes next?<input name="next" maxlength="100" value="Snack or outdoor time"></label><button class="btn full">Start countdown</button></form></div>'}return heading('FIFA & device timer','A visible countdown, agreed matches, next activity, and gentle warnings.')+'<div class="grid">'+part+'<div class="card"><h2>Parent agreement</h2><div class="item"><strong>Before starting</strong><small>Choose a limit and say what comes next.</small></div><div class="item"><strong>Warnings</strong><small>10, 5 and 1 minute reminders while the page is open.</small></div><div class="item"><strong>When it ends</strong><small>Use one calm phrase, avoid arguing, and never wrestle over the device.</small></div><div class="item"><strong>Afterward</strong><small>Praise a safe handover and record the achievement.</small></div><button class="btn soft full" data-action="notifications">Enable browser warnings</button><p class="muted tiny">iPhone browsers may not deliver background alerts. Keep the timer visible; sound or vibration is not guaranteed.</p></div></div>'}
function quickEntry(x,kind){return '<div class="item row"><div><strong>'+esc(x.payload.title||x.payload.behavior||x.payload.note||'Entry')+'</strong><small>'+esc(x.payload.date||'')+'</small></div><button class="btn soft" data-delete="'+x.id+'">×</button></div>'}
function renderBehavior(){let incidents=list('incident').sort((a,b)=>String(b.payload.date).localeCompare(String(a.payload.date)));return heading('Behavior observations','Quickly capture what happened before, what you saw, and how adults responded.')+'<div class="note">A factual log can help identify patterns. It does not diagnose causes. Focus on safety and supportive responses.</div><div class="spacer"></div><div class="grid"><div class="card"><h2>10-second observation</h2><form data-form="incident" class="form"><label>Date<input type="date" name="date" value="'+iso()+'" required></label><label>What happened just before?<select name="before"><option>Device transition</option><option>Sibling interaction</option><option>Unexpected change</option><option>Noise / sensory load</option><option>Tired / hungry</option><option>Not sure</option><option>Other</option></select></label><label>What did you observe?<select name="behavior"><option>Raised voice</option><option>Hitting / unsafe contact</option><option>Throwing objects</option><option>Leaving the area</option><option>Difficulty transitioning</option><option>Other</option></select></label><label>How did adults respond?<select name="after"><option>Separated and checked safety</option><option>Offered a quiet break</option><option>Used one calm reminder</option><option>Moved to another activity</option><option>Other</option></select></label><label>Optional context<textarea name="notes" rows="2" maxlength="500" placeholder="Only objective observations"></textarea></label><button class="btn full">Save observation</button></form></div><div class="card"><div class="row"><h2>Recent observations</h2><span class="tag">'+incidents.length+' total</span></div>'+ (incidents.length?incidents.slice(0,15).map(x=>'<div class="item"><div class="row"><strong>'+esc(x.payload.date)+'</strong><button class="btn soft" data-delete="'+x.id+'">×</button></div><p class="tiny">Before: '+esc(x.payload.before)+'</p><p class="tiny">Observed: '+esc(x.payload.behavior)+'</p><p class="tiny">After: '+esc(x.payload.after)+'</p></div>').join(''):'<p class="muted tiny">Nothing logged. In public demo mode, use made-up examples only.</p>')+'</div></div>'}
function countLast7(kind){let keys=Array.from({length:7},(_,i)=>{let d=new Date();d.setDate(d.getDate()-(6-i));return iso(d)});let dates=list(kind).map(x=>x.payload.date||iso(new Date(x.created_at)));return keys.map(d=>({date:d,count:dates.filter(x=>x===d).length}))}
function bars(rows){let max=Math.max(1,...rows.map(x=>x.count));return '<div class="row" style="align-items:end;gap:5px;height:110px">'+rows.map(x=>'<div style="flex:1;text-align:center"><div style="height:85px;display:flex;align-items:end;justify-content:center"><div title="'+x.count+'" style="border-radius:5px 5px 0 0;background:#5ca58d;width:65%;height:'+Math.max(3,85*x.count/max)+'px"></div></div><small class="muted">'+x.date.slice(8)+'</small></div>').join('')+'</div>'}
function renderProgress(){let wins=list('achievement').sort((a,b)=>String(b.created_at).localeCompare(String(a.created_at))),obs=countLast7('incident'),total=obs.reduce((n,x)=>n+x.count,0);return heading('Positive progress','Notice effort, safe decisions, flexible transitions, and small wins.')+'<div class="grid"><div class="card"><h2>Celebrate a success</h2><form data-form="achievement" class="form"><label>Achievement<select name="title"><option>Peaceful FIFA handover</option><option>Used words to ask for help</option><option>Completed a routine</option><option>Kind interaction with sibling</option><option>Tried a new activity</option><option>Handled a change well</option><option>Other positive moment</option></select></label><label>What helped?<textarea name="notes" rows="2" maxlength="300" placeholder="Brief positive note"></textarea></label><button class="btn full">Record a win ✦</button></form></div><div class="card"><h2>Weekly pattern overview</h2><p class="tiny muted">Observation counts from the last seven days; not a measure of severity.</p><strong style="font-size:28px">'+total+'</strong> <span class="muted">observations</span>'+bars(obs)+'<p class="tiny muted">Look for trends over time, not judgments from one day.</p></div></div><div class="card"><div class="row"><h2>Recent achievements</h2><span class="tag">'+wins.length+' recorded</span></div>'+ (wins.length?wins.slice(0,16).map(x=>'<div class="item row"><div><strong>✦ '+esc(x.payload.title)+'</strong><small>'+esc(x.payload.date)+' '+esc(x.payload.notes||'')+'</small></div><button class="btn soft" data-delete="'+x.id+'">×</button></div>').join(''):'<p class="muted tiny">No achievements yet. Notice and celebrate safe effort.</p>')+'</div>'}
function handoverPreview(){const p=list('handover').sort((a,b)=>String(b.created_at).localeCompare(String(a.created_at)))[0];return p?'<strong>'+esc(p.payload.focus||'Parent update')+'</strong><p class="muted tiny">'+esc(p.payload.note)+'</p>':'<p class="muted tiny">No parent updates yet. Use this for a short, consistent daily handover.</p>'}
function renderHandover(){let notes=list('handover').sort((a,b)=>String(b.created_at).localeCompare(String(a.created_at)));return heading('Parent handover','One shared place for what worked, what changed, and what to do next.')+'<div class="grid"><div class="card"><h2>Write a handover</h2><form data-form="handover" class="form"><label>Main focus<select name="focus"><option>Today went well</option><option>Routine or schedule change</option><option>Device time plan</option><option>Something to watch</option><option>Positive progress</option></select></label><label>Note<textarea name="note" maxlength="600" rows="4" required placeholder="A brief practical update for the other parent"></textarea></label><button class="btn full">Save parent update</button></form></div><div class="card"><h2>Parent updates</h2>'+(notes.length?notes.slice(0,15).map(x=>quickEntry(x,'handover')).join(''):'<p class="muted tiny">No updates yet.</p>')+'</div></div>'}
function renderExtra(kind){let isMeal=kind==='food',name=isMeal?'Food & meals':'Needs & supports',options=isMeal?['Reliable food','Meal idea','Food to explore','Avoid / confirmed allergy']:['Strength','Possible trigger','Helpful strategy','Communication'];return heading(name,isMeal?'Familiar options and meal routines.':'What Gavriel enjoys, what may overwhelm him, and what helps.')+'<div class="grid"><div class="card"><h2>Add '+(isMeal?'food':'insight')+'</h2><form class="form" data-form="'+kind+'"><label>Category<select name="category">'+options.map(x=>'<option>'+x+'</option>').join('')+'</select></label><label>Title<input name="title" maxlength="100" required></label><label>Notes<textarea name="notes" rows="3" maxlength="500"></textarea></label><button class="btn full">Save</button></form></div><div class="card"><h2>Saved notes</h2>'+ (list(kind).length?list(kind).map(x=>'<div class="item row"><div><strong>'+esc(x.payload.title)+'</strong><small>'+esc(x.payload.category)+' · '+esc(x.payload.notes||'')+'</small></div><button data-delete="'+x.id+'" class="btn soft">×</button></div>').join(''):'<p class="tiny muted">Nothing added yet.</p>')+'</div></div>'}
function renderMore(){return heading('More tools','Family tools and planning details.')+'<div class="card">'+EXTRAS.map(x=>'<div class="item row"><div><strong>'+x[1]+' '+x[2]+'</strong></div><button class="btn soft" data-tab="'+x[0]+'">Open →</button></div>').join('')+'</div>'+safety()}
function renderAuth(){return heading('Parent accounts','Private shared access is separate from the public demo.')+'<div class="card"><h2>Sign in or create a parent account</h2><p class="tiny muted">Each parent uses their own verified email address. A setup or invite code is required before accessing family records.</p><form class="form" data-form="auth"><label>Email<input type="email" name="email" autocomplete="email" required></label><label>Password (10+ characters)<input type="password" name="password" minlength="10" autocomplete="current-password" required></label><div class="twocol"><button type="submit" class="btn" name="intent" value="signin">Sign in</button><button type="submit" class="btn soft" name="intent" value="signup">Create account</button></div></form><p class="tiny muted">New accounts may need email confirmation. Return here and sign in after confirming.</p><button class="btn soft" data-action="leavecloud">Return to public demo</button></div>'}
