function renderFamily(){if(state.mode==='cloud'&&!state.user)return renderAuth();if(state.mode==='cloud'&&!state.family)return renderSetup();return heading('Family & sync','Parent accounts, private invitations, and data backup.')+'<div class="grid"><div class="card"><h2>Shared access</h2>'+(state.mode==='cloud'?'<div class="note"><strong>Secure family sync active</strong><br>Changes are shared only with authorized household members.</div><p class="tiny muted">Parent account: '+esc(state.user?.email||'')+'</p><label class="form"><strong>Private family invite</strong><input id="invite" readonly value="'+esc(state.family?.invite_code||'')+'"></label><div class="spacer"></div><button class="btn soft" data-action="copyinvite">Copy invitation code</button><div class="spacer"></div><button class="btn soft" data-action="signout">Sign out</button>':'<p class="tiny muted">The public demo is not synced. Your family database is ready to use after verified parent sign-in.</p><button class="btn" data-action="cloud">Enable private parent sync</button>')+'</div><div class="card"><h2>Protect your family</h2><p class="tiny">The public demo is open to visitors and should never contain real child-specific notes.</p><p class="tiny">Private mode requires individual parent accounts and membership controls. Use phone passcodes and share invite codes only with the other parent.</p><button class="btn soft" data-action="export">Export records to JSON</button></div></div>'}
function modalSafety(){$('modalRoot').innerHTML='<div class="dialog" id="backdrop"><div class="modal"><div class="row"><h2>Immediate response plan</h2><button class="btn soft" data-action="close">Close</button></div>'+safety()+'</div></div>'}
function view(){nav();updateStatus();let p=state.tab;if(state.mode==='cloud'&&!state.user&&p!=='family')p='family';if(state.mode==='cloud'&&!state.family&&p!=='family')p='family';const v={today:renderToday,routines:renderRoutines,calendar:renderCalendar,fifa:renderFifa,progress:renderProgress,behavior:renderBehavior,handover:renderHandover,more:renderMore,meals:()=>renderExtra('food'),needs:()=>renderExtra('need'),family:renderFamily};$('main').innerHTML=(v[p]||renderToday)()+'<footer>Gavriel Family Hub · '+(state.mode==='cloud'?'Authorized parent space':'Public interactive demo')+' · Not a medical or crisis service</footer>'}
async function refresh(){if(state.mode!=='cloud'||!state.user||!state.family)return;try{let q=await state.client.from('gfh_family_records').select('*').eq('household_id',state.family.id).order('created_at',{ascending:false}).limit(1000);if(q.error)throw q.error;state.items=q.data||[];view()}catch(e){message('Sync error: '+e.message)}}
async function persist(kind,payload,id){if(state.mode==='cloud'){if(!state.user||!state.family)throw Error('Sign in first');let q=id?await state.client.from('gfh_family_records').update({payload,updated_at:now()}).eq('id',id).eq('household_id',state.family.id).select().single():await state.client.from('gfh_family_records').insert({kind,payload,household_id:state.family.id,created_by:state.user.id}).select().single();if(q.error)throw q.error;await refresh()}else{if(id){state.items=state.items.map(x=>x.id===id?{...x,payload}:x)}else state.items.unshift({id:uid(),kind,payload,created_at:now()});localStorage.setItem(KEY,JSON.stringify(state.items));view()}}
async function discard(id){if(!confirm('Delete this entry?'))return;try{if(state.mode==='cloud'){let q=await state.client.from('gfh_family_records').delete().eq('id',id).eq('household_id',state.family.id);if(q.error)throw q.error;await refresh()}else{state.items=state.items.filter(x=>x.id!==id);localStorage.setItem(KEY,JSON.stringify(state.items));view()}}catch(e){message(e.message)}}
async function loadFamily(){const member=await state.client.from('gfh_family_members').select('household_id').eq('user_id',state.user.id).maybeSingle();if(member.error)throw member.error;if(!member.data){state.family=null;view();return}const h=await state.client.from('gfh_households').select('id,name,invite_code,owner_id').eq('id',member.data.household_id).single();if(h.error)throw h.error;state.family=h.data;if(window.__gfhChannel)await state.client.removeChannel(window.__gfhChannel);window.__gfhChannel=state.client.channel('gfh-private-'+h.data.id).on('postgres_changes',{event:'*',schema:'public',table:'gfh_family_records',filter:'household_id=eq.'+h.data.id},()=>refresh()).subscribe();await refresh()}
async function startCloud(){state.mode='cloud';state.items=[];state.user=null;state.family=null;localStorage.setItem('gfh_mode','cloud');state.tab='family';view();try{const lib=await import('https://esm.sh/@supabase/supabase-js@2.118.0');state.client=lib.createClient(SB_URL,SB_KEY,{auth:{persistSession:true,autoRefreshToken:true,detectSessionInUrl:true}});let {data,error}=await state.client.auth.getSession();if(error)throw error;state.user=data.session?.user||null;state.client.auth.onAuthStateChange((_e,session)=>{setTimeout(async()=>{if(state.mode!=='cloud')return;state.user=session?.user||null;if(state.user){try{await loadFamily()}catch(e){message('Family sync: '+e.message)}}else{state.family=null;view()}},0)});if(state.user)await loadFamily();else view()}catch(e){message('Could not connect: '+e.message)}}
function leaveCloud(){if(window.__gfhChannel&&state.client)state.client.removeChannel(window.__gfhChannel);state.mode='demo';state.user=null;state.family=null;state.items=loadDemo();state.tab='today';localStorage.setItem('gfh_mode','demo');view()}
async function signOut(){if(state.client)await state.client.auth.signOut();leaveCloud()}
function tick(){let a=activeSession(),label=$('bigClock');if(!label||!a)return;let left=(new Date(a.payload.ends_at)-Date.now())/1000;label.textContent=clock(left);let f=$('timerFill');if(f)f.style.width=Math.max(0,Math.min(100,left/(a.payload.minutes*60)*100))+'%';let st=$('timerStatus');if(st)st.textContent=left<=0?'TIME IS UP':'SESSION IN PROGRESS';let hint=$('timerHint');if(hint)hint.textContent=left<=0?'Time is finished. Offer the next activity calmly.':left<=60?'1 minute or less: finish the current match.':left<=300?'5 minutes or less: help prepare the handover.':'Keep the agreed ending time visible.';for(let threshold of [600,300,60]){if(left<=threshold&&left>threshold-3&&a.payload.minutes*60>threshold){let k=a.id+':'+threshold;if(!state.warnings.has(k)){state.warnings.add(k);if(document.visibilityState==='visible')message(threshold/60+' minute FIFA warning: prepare to finish.');if('vibrate' in navigator)navigator.vibrate([130,80,130]);if('Notification' in window&&Notification.permission==='granted'){try{new Notification('FIFA: '+threshold/60+' minutes left',{body:'Prepare the next activity and avoid starting another match.'})}catch{}}}}}}
document.addEventListener('click',async ev=>{const b=ev.target.closest('button');if(!b)return;try{if(b.dataset.tab){state.tab=b.dataset.tab;view();scrollTo(0,0)}else if(b.dataset.check){let x=find(b.dataset.check);if(x)await persist('routine',{...x.payload,done_on:x.payload.done_on===iso()?'':iso()},x.id)}else if(b.dataset.delete){await discard(b.dataset.delete)}else if(b.dataset.day){state.selected=b.dataset.day;view()}else if(b.dataset.month){state.month.setMonth(state.month.getMonth()+Number(b.dataset.month));state.selected=iso(new Date(state.month));view()}else if(b.dataset.action==='safety'){modalSafety()}else if(b.dataset.action==='close'){ $('modalRoot').innerHTML=''}else if(b.dataset.action==='finish'){let x=activeSession();if(x){await persist('screen',{...x.payload,status:'finished',finished_at:now()},x.id);message('Controller returned. Celebrate a safe handover.')}}else if(b.dataset.action==='notifications'){if('Notification' in window){let p=await Notification.requestPermission();message(p==='granted'?'Notifications enabled while the page is open.':'Keep the on-screen timer visible.')}else message('This browser does not support permission-based alerts.')}else if(b.dataset.action==='cloud'){await startCloud()}else if(b.dataset.action==='leavecloud'){leaveCloud()}else if(b.dataset.action==='signout'){await signOut()}else if(b.dataset.action==='copyinvite'){await navigator.clipboard.writeText(state.family.invite_code);message('Invite copied. Share privately.')}else if(b.dataset.action==='export'){let blob=new Blob([JSON.stringify(state.items,null,2)],{type:'application/json'});let url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download='gavriel-family-hub-backup.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)}}catch(e){message('Action error: '+e.message)}});
document.addEventListener('submit',async ev=>{const f=ev.target;if(!f.dataset.form)return;ev.preventDefault();if(state.busy)return;state.busy=true;const d=Object.fromEntries(new FormData(f).entries());try{const type=f.dataset.form;if(type==='auth'){if(!state.client)throw Error('Connection not ready');let intent=ev.submitter?.value||'signin';if(intent==='signup'){let out=await state.client.auth.signUp({email:d.email.trim(),password:d.password});if(out.error)throw out.error;message(out.data.session?'Account created. Open Family & Sync.':'Check your email to confirm, then return to sign in.')}else{let out=await state.client.auth.signInWithPassword({email:d.email.trim(),password:d.password});if(out.error)throw out.error;state.user=out.data.user;await loadFamily()}}else if(type==='createfamily'){let r=await state.client.rpc('gfh_create_family',{p_name:d.name,p_activation:d.activation.trim()});if(r.error)throw r.error;await loadFamily();message('Private family created. Invite the other parent from Family & Sync.')}else if(type==='joinfamily'){let r=await state.client.rpc('gfh_join_family',{p_code:d.code.trim()});if(r.error)throw r.error;await loadFamily();message('Joined the family space.')}else{let payload={...d};if(type==='routine')payload.done_on='';if(type==='schedule'){if(d.repeat==='sunfri'){payload.repeat='weekly';payload.weekdays=[0,1,2,3,4,5]}else if(d.repeat==='weekly'){payload.repeat='weekly';payload.weekdays=[new Date(d.date+'T12:00:00').getDay()]}else if(d.repeat==='daily'){payload.repeat='daily';payload.weekdays=[0,1,2,3,4,5,6]}else{delete payload.repeat}}if(type==='achievement')payload.date=iso();if(type==='handover')payload.date=iso();if(type==='screen'){const active=activeSession();if(active)throw Error('Finish current session first');const minutes=Number(d.minutes);payload={...d,minutes,status:'running',started_at:now(),ends_at:new Date(Date.now()+minutes*60000).toISOString()};state.warnings.clear()}await persist(type,payload);message('Saved '+(state.mode==='cloud'?'to your private shared family space.':'on this phone’s demo only.'))}}catch(e){message('Could not save: '+e.message)}finally{state.busy=false}});
window.addEventListener('visibilitychange',()=>{if(document.visibilityState==='visible'&&state.mode==='cloud'&&state.family)refresh()});
view();if(state.mode==='cloud')startCloud();setInterval(tick,1000);setInterval(()=>{if(state.mode==='cloud'&&state.family&&document.visibilityState==='visible')refresh()},30000);
